<?php
require_once __DIR__.'/../../app/layout.php';require_role('company');$uid=(int)current_user()['id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$status=in_array($_POST['status']??'',['Menunggu','Ditinjau','Diproses','Diterima','Ditolak'],true)?$_POST['status']:'Menunggu';$st=db()->prepare('UPDATE applications a JOIN jobs j ON j.id=a.job_id SET a.status=? WHERE a.id=? AND j.company_id=?');$st->execute([$status,(int)$_POST['application_id'],$uid]);flash('success','Status lamaran diperbarui.');redirect('company/applicants.php');}
$st=db()->prepare("SELECT a.*,j.title,u.name candidate,u.email,cp.headline,cp.skills,cp.experience,cp.education,cp.accessibility_needs,cp.portfolio_url FROM applications a JOIN jobs j ON j.id=a.job_id JOIN users u ON u.id=a.candidate_id LEFT JOIN candidate_profiles cp ON cp.user_id=u.id WHERE j.company_id=? ORDER BY a.created_at DESC");$st->execute([$uid]);$list=$st->fetchAll();page_header('Kelola kandidat');?>
<section class="page-hero"><div class="container"><span class="eyebrow">DASHBOARD PERUSAHAAN</span><h1>Kandidat dan lamaran</h1><p>Tinjau keterampilan dan pengalaman kandidat serta perbarui status lamaran.</p></div></section><section class="section"><div class="container"><?php if(!$list):?><div class="empty"><h2>Belum ada kandidat</h2><p>Lamaran akan muncul setelah pencari kerja mengirimkan aplikasi.</p></div><?php endif;?><?php foreach($list as $a):?><article class="panel applicant"><div class="applicant-head"><div class="company-logo"><?=e(initials($a['candidate']))?></div><div><h2><?=e($a['candidate'])?></h2><p class="muted"><?=e($a['headline']?:'Pencari kerja')?> · <?=e($a['title'])?></p></div><span class="badge <?=e(badge_class($a['status']))?>"><?=e($a['status'])?></span></div><div class="applicant-data"><div><b>Keterampilan</b><p><?=e($a['skills']?:'Belum diisi')?></p></div><div><b>Pendidikan</b><p><?=e($a['education']?:'Belum diisi')?></p></div><div><b>Pengalaman</b><p class="preserve"><?=e($a['experience']?:'Belum diisi')?></p></div><div><b>Akomodasi (jika disampaikan)</b><p class="preserve"><?=e($a['accessibility_needs']?:'Tidak disampaikan')?></p></div><div><b>Pesan lamaran</b><p class="preserve"><?=e($a['cover_letter']?:'Tidak ada pesan tambahan.')?></p></div></div><div class="actions"><a class="link" href="mailto:<?=e($a['email'])?>">Hubungi kandidat ↗</a><?php if($a['portfolio_url']):?><a class="link" href="<?=e($a['portfolio_url'])?>" target="_blank" rel="noopener">Portofolio ↗</a><?php endif;?><form method="post" class="status-form"><?=csrf_field()?><input type="hidden" name="application_id" value="<?=(int)$a['id']?>"><label class="sr-only" for="s<?=(int)$a['id']?>">Status lamaran</label><select id="s<?=(int)$a['id']?>" name="status"><?php foreach(['Menunggu','Ditinjau','Diproses','Diterima','Ditolak'] as $s):?><option <?=$a['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn btn-primary btn-sm">Perbarui</button></form></div></article><?php endforeach;?></div></section><?php page_footer();?>
